    34→public class ExecutionProcessorTests
    35→{
    36→    private ISpecProvider _specProvider;
    37→    private ITransactionProcessor _transactionProcessor;
    38→    private IWorldState _stateProvider;
    39→    private IReleaseSpec _spec;
    40→    private IDisposable _worldStateCloser;
    41→    private static readonly UInt256 AccountBalance = 1.Ether();
    42→    private static readonly Address DepositContractAddress = Eip6110Constants.MainnetDepositContractAddress;
    43→    private static readonly Address eip7002Account = Eip7002Constants.WithdrawalRequestPredeployAddress;
    44→    private static readonly Address eip7251Account = Eip7251Constants.ConsolidationRequestPredeployAddress;
    45→    private static readonly AbiSignature _depositEventABI = new("DepositEvent", AbiType.DynamicBytes, AbiType.DynamicBytes, AbiType.DynamicBytes, AbiType.DynamicBytes, AbiType.DynamicBytes);
    46→    private static readonly AbiEncoder _abiEncoder = AbiEncoder.Instance;
    47→
    48→    private static readonly TestExecutionRequest[] _executionDepositRequests = [TestItem.ExecutionRequestA, TestItem.ExecutionRequestB, TestItem.ExecutionRequestC];
    49→    private static readonly TestExecutionRequest[] _executionWithdrawalRequests = [TestItem.ExecutionRequestD, TestItem.ExecutionRequestE, TestItem.ExecutionRequestF];
    50→    private static readonly TestExecutionRequest[] _executionConsolidationRequests = [TestItem.ExecutionRequestG, TestItem.ExecutionRequestH, TestItem.ExecutionRequestI];
    51→
    52→    private void FlatEncodeWithoutType(ExecutionRequest[] requests, Span<byte> buffer)
    53→    {
    54→        int currentPosition = 0;
    55→
    56→        foreach (ExecutionRequest request in requests)
    57→        {
    58→            // Ensure the buffer has enough space to accommodate the new data
    59→            if (currentPosition + request.RequestData!.Length > buffer.Length)
    60→            {
    61→                throw new InvalidOperationException("Buffer is not large enough to hold all data of requests");
    62→            }
    63→
    64→            // Copy the RequestData to the buffer at the current position
    65→            request.RequestData.CopyTo(buffer.Slice(currentPosition, request.RequestData.Length));
    66→            currentPosition += request.RequestData.Length;
    67→        }
    68→    }
    69→
    70→    [SetUp]
    71→    public void Setup()
    72→    {
    73→        _specProvider = MainnetSpecProvider.Instance;
    74→        IWorldStateManager worldStateManager = TestWorldStateFactory.CreateForTest();
    75→        _stateProvider = worldStateManager.GlobalWorldState;
    76→        _worldStateCloser = _stateProvider.BeginScope(IWorldState.PreGenesis);
    77→        _stateProvider.CreateAccount(eip7002Account, AccountBalance);
    78→        _stateProvider.CreateAccount(eip7251Account, AccountBalance);
    79→
    80→        _stateProvider.InsertCode(eip7002Account, Eip7002TestConstants.CodeHash, Eip7002TestConstants.Code, Prague.Instance);
    81→        _stateProvider.InsertCode(eip7251Account, Eip7251TestConstants.CodeHash, Eip7251TestConstants.Code, Prague.Instance);
    82→        _stateProvider.Commit(_specProvider.GenesisSpec);
    83→        _stateProvider.CommitTree(0);
    84→
    85→        _spec = Substitute.For<IReleaseSpec>();
    86→
    87→        _spec.RequestsEnabled.Returns(true);
    88→        _spec.DepositsEnabled.Returns(true);
    89→        _spec.WithdrawalRequestsEnabled.Returns(true);
    90→        _spec.ConsolidationRequestsEnabled.Returns(true);
    91→
    92→        _spec.DepositContractAddress.Returns(DepositContractAddress);
    93→        _spec.Eip7002ContractAddress.Returns(eip7002Account);
    94→        _spec.Eip7251ContractAddress.Returns(eip7251Account);
    95→
    96→        _transactionProcessor = Substitute.For<ITransactionProcessor>();
    97→
    98→        _transactionProcessor.Execute(Arg.Any<Transaction>(), Arg.Any<CallOutputTracer>())
    99→            .Returns(ci =>
   100→            {
   101→                Transaction transaction = ci.Arg<Transaction>();
   102→                CallOutputTracer tracer = ci.Arg<CallOutputTracer>();
   103→
   104→                tracer.StatusCode = StatusCode.Success;
   105→
   106→                if (transaction.To == eip7002Account)
   107→                {
   108→                    Span<byte> buffer = new byte[GetRequestsByteSize(_executionWithdrawalRequests)];
   109→                    FlatEncodeWithoutType(_executionWithdrawalRequests, buffer);
   110→                    tracer.ReturnValue = buffer.ToArray();
   111→                }
   112→                else if (transaction.To == eip7251Account)
   113→                {
   114→                    Span<byte> buffer = new byte[GetRequestsByteSize(_executionConsolidationRequests)];
   115→                    FlatEncodeWithoutType(_executionConsolidationRequests, buffer);
   116→                    tracer.ReturnValue = buffer.ToArray();
   117→                }
   118→                else
   119→                {
   120→                    tracer.ReturnValue = [];
   121→                }
   122→                return new TransactionResult();
   123→
   124→                static int GetRequestsByteSize(IEnumerable<ExecutionRequest> requests) => requests.Sum(r => r.RequestData.Length);
   125→            });
   126→    }
   127→
   128→    [TearDown]
   129→    public void TearDown()
   130→    {
   131→        _worldStateCloser?.Dispose();
   132→    }
   133→
   134→    private static Hash256 CalculateHash(
   135→        TestExecutionRequest[] depositRequests,
   136→        TestExecutionRequest[] withdrawalRequests,
   137→        TestExecutionRequest[] consolidationRequests
   138→    )
   139→    {
   140→        using ArrayPoolList<byte[]> requests = TestExecutionRequestExtensions.GetFlatEncodedRequests(depositRequests, withdrawalRequests, consolidationRequests);
   141→        return ExecutionRequestExtensions.CalculateHashFromFlatEncodedRequests(requests.ToArray());
   142→    }
   143→
   144→    [Test]
   145→    public void ShouldNotProcessExecutionRequestsForGenesisBlock()
   146→    {
   147→        Block block = Build.A.Block.WithNumber(0).TestObject;
   148→        ExecutionRequestsProcessor executionRequestsProcessor = new(_transactionProcessor);
   149→
   150→        TxReceipt[] txReceipts = [
   151→            Build.A.Receipt.WithLogs(
   152→                CreateLogEntry(TestItem.ExecutionRequestA.RequestDataParts)
   153→            ).TestObject
   154→        ];
   155→        _transactionProcessor.SetBlockExecutionContext(new BlockExecutionContext(block.Header, _spec));
   156→        executionRequestsProcessor.ProcessExecutionRequests(block, _stateProvider, txReceipts, _spec);
   157→
   158→        Assert.That(block.Header.RequestsHash, Is.Null);
   159→    }
   160→
   161→    [Test]
   162→    public void ShouldProcessExecutionRequests()
   163→    {
   164→        Block block = Build.A.Block.WithNumber(1).TestObject;
   165→        ExecutionRequestsProcessor executionRequestsProcessor = new(_transactionProcessor);
   166→
   167→        TxReceipt[] txReceipts = [
   168→            Build.A.Receipt.WithLogs(
   169→                CreateLogEntry(TestItem.ExecutionRequestA.RequestDataParts),
   170→                CreateLogEntry(TestItem.ExecutionRequestB.RequestDataParts),
   171→                CreateLogEntry(TestItem.ExecutionRequestC.RequestDataParts)
   172→            ).TestObject
   173→        ];
   174→        _transactionProcessor.SetBlockExecutionContext(new BlockExecutionContext(block.Header, _spec));
